{
  "components": [
    {
      "type": "entity",
      "quote": "Servizio d'inchiesta svizzero sulla sicurezza (SISI)",
      "gist": "Swiss Safety Investigation Service (SISI)"
    },
    {
      "type": "claim",
      "quote": "Il Servizio d'inchiesta svizzero sulla sicurezza (SISI) è l'organo statale della Confederazione Svizzera incaricato di svolgere indagini su incidenti ed eventi pericolosi nell'ambito delle ferrovie, aeromobili, battelli e navi.",
      "gist": "SISI is the Swiss federal body responsible for investigating railway, aircraft, boat, and ship incidents and dangerous events."
    },
    {
      "type": "claim",
      "quote": "Queste attività hanno lo scopo di accertare non solo le cause dirette di tali eventi, ma anche i loro motivi più profondi e altri rischi a essi correlati.",
      "gist": "These activities aim to determine not only the direct causes of such events but also their deeper reasons and related risks."
    },
    {
      "type": "claim",
      "quote": "Le indagini hanno il solo obiettivo di ottenere informazioni grazie alle quali si possa prevenire in futuro incidenti e situazioni di pericolo e quindi garantire una maggiore sicurezza.",
      "gist": "Investigations aim solely to gather information to prevent future incidents and dangerous situations, thereby ensuring greater safety."
    },
    {
      "type": "claim",
      "quote": "I risultati delle indagini non hanno lo scopo di chiarire questioni relative alla colpa e alla responsabilità.",
      "gist": "The results of the investigations do not aim to clarify issues of guilt and responsibility."
    }
  ]
}
